-- ============================================================
-- V5 -- LCR Table Redesign + Sample Data
-- Target: MS SQL Server Developer Edition
-- ============================================================
--
-- Changes from V3:
--   1. Drop all four LCR tables (empty, no data loss).
--   2. Recreate LCR_REPORT_LINE with corrected unique constraint:
--        UQ(v_report_code, v_para_code, v_report_line_code)
--      Some line codes (22209, 21501) appear under different para-codes
--      / hierarchy positions, so the old constraint
--      UQ(v_report_code, v_report_line_code) was too narrow.
--   3. Other three tables unchanged structurally.
--   4. Insert sample data from both osfi-lcr.json and osfi-lcr-metric.json.
-- ============================================================

-- ===================== DROP OLD (EMPTY) TABLES =====================

IF EXISTS (SELECT 1 FROM sys.tables WHERE name = 'LCR_REPORT_DATA')
    DROP TABLE LCR_REPORT_DATA;
GO

IF EXISTS (SELECT 1 FROM sys.tables WHERE name = 'LCR_REPORT_LINE_LEVEL')
    DROP TABLE LCR_REPORT_LINE_LEVEL;
GO

IF EXISTS (SELECT 1 FROM sys.tables WHERE name = 'LCR_SEGMENT')
    DROP TABLE LCR_SEGMENT;
GO

IF EXISTS (SELECT 1 FROM sys.tables WHERE name = 'LCR_REPORT_LINE')
    DROP TABLE LCR_REPORT_LINE;
GO

-- ===================== LCR_REPORT_LINE =====================

CREATE TABLE LCR_REPORT_LINE (
    id                  BIGINT          IDENTITY(1,1) NOT NULL,
    v_report_code       NVARCHAR(50)    NOT NULL,
    v_para_code         NVARCHAR(50)    NOT NULL DEFAULT '',
    v_report_line_code  NVARCHAR(10)    NOT NULL,
    v_report_line_name  NVARCHAR(500)   NOT NULL,
    CONSTRAINT PK_LCR_REPORT_LINE PRIMARY KEY (id),
    CONSTRAINT UQ_LCR_REPORT_LINE UNIQUE (v_report_code, v_para_code, v_report_line_code)
);
GO

-- ===================== LCR_REPORT_LINE_LEVEL =====================

CREATE TABLE LCR_REPORT_LINE_LEVEL (
    id              BIGINT      IDENTITY(1,1) NOT NULL,
    report_line_id  BIGINT      NOT NULL,
    n_level_order   INT         NOT NULL,
    v_level_code    NVARCHAR(10)    NOT NULL,
    v_level_desc    NVARCHAR(255)   NOT NULL,
    CONSTRAINT PK_LCR_REPORT_LINE_LEVEL PRIMARY KEY (id),
    CONSTRAINT FK_LCR_LINE_LEVEL_LINE FOREIGN KEY (report_line_id) REFERENCES LCR_REPORT_LINE(id),
    CONSTRAINT UQ_LCR_LINE_LEVEL UNIQUE (report_line_id, n_level_order)
);
GO

-- ===================== LCR_SEGMENT =====================

CREATE TABLE LCR_SEGMENT (
    id              BIGINT          IDENTITY(1,1) NOT NULL,
    n_segment_order INT             NOT NULL,
    v_segment_name  NVARCHAR(100)   NOT NULL,
    CONSTRAINT PK_LCR_SEGMENT PRIMARY KEY (id),
    CONSTRAINT UQ_LCR_SEGMENT_NAME UNIQUE (v_segment_name)
);
GO

-- ===================== LCR_REPORT_DATA =====================

CREATE TABLE LCR_REPORT_DATA (
    id                      BIGINT          IDENTITY(1,1) NOT NULL,
    report_line_id          BIGINT          NOT NULL,
    segment_id              BIGINT          NOT NULL,
    n_date_skey             INT             NOT NULL,
    d_calander_date         DATE            NOT NULL,
    n_amount_rpt_ccy        DECIMAL(20,5)   NOT NULL DEFAULT 0,
    n_rw_amount_rpt_ccy     DECIMAL(20,5)   NULL,
    CONSTRAINT PK_LCR_REPORT_DATA PRIMARY KEY (id),
    CONSTRAINT FK_LCR_DATA_REPORT_LINE FOREIGN KEY (report_line_id) REFERENCES LCR_REPORT_LINE(id),
    CONSTRAINT FK_LCR_DATA_SEGMENT FOREIGN KEY (segment_id) REFERENCES LCR_SEGMENT(id),
    CONSTRAINT UQ_LCR_REPORT_DATA UNIQUE (report_line_id, segment_id, n_date_skey)
);
GO

-- ===================== INDEXES =====================

CREATE NONCLUSTERED INDEX IX_LCR_REPORT_LINE_CODE ON LCR_REPORT_LINE (v_report_code);
GO
CREATE NONCLUSTERED INDEX IX_LCR_REPORT_LINE_LEVEL_LINE ON LCR_REPORT_LINE_LEVEL (report_line_id);
GO
CREATE NONCLUSTERED INDEX IX_LCR_REPORT_DATA_DATE ON LCR_REPORT_DATA (d_calander_date);
GO
CREATE NONCLUSTERED INDEX IX_LCR_REPORT_DATA_LINE_DATE ON LCR_REPORT_DATA (report_line_id, d_calander_date);
GO

-- ===================== SAMPLE DATA =====================

-- Segments
SET IDENTITY_INSERT LCR_SEGMENT ON;
SET IDENTITY_INSERT LCR_SEGMENT OFF;
GO

-- Report Lines
SET IDENTITY_INSERT LCR_REPORT_LINE ON;
SET IDENTITY_INSERT LCR_REPORT_LINE OFF;
GO

-- Report Line Levels
SET IDENTITY_INSERT LCR_REPORT_LINE_LEVEL ON;
SET IDENTITY_INSERT LCR_REPORT_LINE_LEVEL OFF;
GO

-- Report Data
SET IDENTITY_INSERT LCR_REPORT_DATA ON;

-- OSFI_LCR data

-- OSFI_LCR_METRIC data

SET IDENTITY_INSERT LCR_REPORT_DATA OFF;
GO

